function rtRun(text,fmt){fmt=fmt||{};return {text:text,bold:!!fmt.bold,italic:!!fmt.italic,underline:!!fmt.underline};}
function rtHtml(runs){return runs.map(function(r){var t=r.text.replace(/&/g,'&amp;').replace(/</g,'&lt;');if(r.bold)t='<b>'+t+'</b>';if(r.italic)t='<i>'+t+'</i>';if(r.underline)t='<u>'+t+'</u>';return t;}).join('');}
function rtText(runs){return runs.map(function(r){return r.text;}).join('');}
function rtToggle(runs,mark){runs.forEach(function(r){r[mark]=!r[mark];});return runs;}
